            diag: [{ p: '(네 |)오늘(은|) (정말 |)춥어요', note: 'ㅂ + vowel ending: ㅂ → 우. 추 + 우 + 어요 = 추워요.' }, { p: '(네 |)오늘(은|) (정말 |)추와요', note: '와 is only for 돕다. 춥다 → 추워요.' }, { p: '(네 |)오늘(은|) (정말 |)더워요', note: '더워요 = it’s hot. Cold: 추워요.' }],
