MM.mnemo[11] = {"cards":[{"id":"ko-k3-0221","w":"돕다","cs":"pomoci; pomáhat","en":"to help","p":"v","o":"k","ex":"돕는 것","exc":"pomáhání; to, že někdo pomáhá (-는 것 → podstatné jméno slovesné)","m":"Nepravidelné časování ㅂ: před koncovkou -아요/-어요 se ㅂ mění na 오 (ne na 우!), tedy 도와요 (pomáhám). Podstatné jméno je 도움 (pomoc).","tv":["도와요","도왔어요","도울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0222","w":"춥다","cs":"studený; chladný; být zima (o počasí)","en":"to be cold","p":"a","o":"k","ex":"서울은 겨울에 정말 추워요.","exc":"V Soulu je v zimě opravdu zima. (은 → téma; 에 → kdy)","m":"Nepravidelné časování ㅂ → 추워요. Používá se pro počasí a pocit chladu (opak 덥다 = být horko); pro studené věci a nápoje je 차갑다.","tv":["추워요","추웠어요","추울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0223","w":"귀엽다","cs":"roztomilý; milý","en":"to be cute","p":"a","o":"k","ex":"이거 너무 귀여워요.","exc":"Tohle je tak roztomilé.","m":"Nepravidelné časování ㅂ → 귀여워요. Používá se pro děti, zvířata i roztomilé věci.","tv":["귀여워요","귀여웠어요","귀여울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0224","w":"굽다","cs":"péct, grilovat","en":"to bake","p":"v","o":"k","rz":["굽다 → 구워요","péct → peču"],"m":"Nepravidelné ㅂ: 구워요, 구운 고기 (grilované maso). Pozor na 눕다 (lehnout si → 누워요).","tv":["구워요","구웠어요","구울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0225","w":"눕다","cs":"lehnout si; ležet","en":"to lie down","p":"v","o":"k","rz":["눕다 → 누워요","lehnout si → lehám si"],"m":"Nepravidelné časování ㅂ → 누워요. Pozor na záměnu se slovesem 굽다 (péct, grilovat → 구워요).","tv":["누워요","누웠어요","누울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0226","w":"밉다","cs":"protivný; nesympatický; ošklivý (chováním)","en":"to hate","p":"a","o":"k","ex":"미운 것","exc":"něco protivného; protivná věc (-ㄴ 것 → přívlastek)","m":"Nepravidelné časování ㅂ → 미워요, před podstatným jménem 미운. V korejštině je to přídavné jméno (‚být protivný‘), sloveso ‚nenávidět‘ je 미워하다.","tv":["미워요","미웠어요","미울 거예요"],"irr":"ㅂ"},{"id":"ko-k3-0227","w":"입다","cs":"obléknout si; nosit (oblečení)","en":"to wear","p":"v","o":"k","rz":["입다 → 입어요","obléknout si → oblékám si (ne 이워요)"],"m":"Pravidelné sloveso na ㅂ: ㅂ nemizí, proto 입어요 (ne 이워요!). Používá se pro oblečení na trup a kalhoty (na boty je 신다, na čepici 쓰다).","tv":["입어요","입었어요","입을 거예요"]},{"id":"ko-k3-0228","w":"씹다","cs":"žvýkat; kousat","en":"to bite","p":"v","o":"k","rz":["씹으면 · 씹고 · 씹어서","když žvýkáš · žvýkat a · rozžvýkat a pak (-으면 → když; -고 → a; -어서 → a pak)"],"m":"Pravidelné sloveso na ㅂ: ㅂ zůstává ve všech tvarech (씹어요, 씹으면). Časté spojení: 껌을 씹다 = žvýkat žvýkačku.","tv":["씹어요","씹었어요","씹을 거예요"]},{"id":"ko-k3-0229","w":"좁다","cs":"úzký; těsný","en":"to be narrow","p":"a","o":"k","rz":["좁다 → 좁아요","úzký → je úzký"],"m":"Pravidelné přídavné jméno na ㅂ: ㅂ zůstává, proto 좁아요 (ne 조와요!). Opak 넓다 (široký).","tv":["좁아요","좁았어요","좁을 거예요"]},{"id":"ko-k3-0230","w":"넓다","cs":"široký; prostorný","en":"to be wide","p":"a","o":"k","rz":["넓다 → 넓어요","široký → je široký"],"m":"Výslovnost [널따], před samohláskou [널버요] (넓어요). Pravidelné časování. Opak 좁다 (úzký).","tv":["넓어요","넓었어요","넓을 거예요"]},{"id":"ko-k3-0231","w":"문제","cs":"úloha, otázka; problém","en":"problem; question","p":"n","o":"s","ex":"이 문제는 어려워요.","exc":"Tahle úloha je těžká. (는 → téma)","m":"問 ptát se + 題 téma = položená otázka. 시험 문제 = otázka v testu, 문제가 생기다 = nastat problém.","r":["mun-問","je-題"]},{"id":"ko-k3-0232","w":"겨울","cs":"zima (roční období)","en":"winter","p":"n","o":"k","ex":"서울은 겨울에 정말 추워요.","exc":"V Soulu je v zimě opravdu zima. (은 → téma; 에 → kdy)","m":"Čtyři roční období: 봄 (jaro), 여름 (léto), 가을 (podzim), 겨울 (zima). Zimní prázdniny jsou 겨울 방학."},{"id":"ko-k3-0233","w":"정말","cs":"opravdu; skutečně; vskutku","en":"really","p":"o","o":"m","ex":"어제는 정말 추웠어요.","exc":"Včera byla opravdu zima. (는 → téma)","m":"正 správný, pravý + 말 slovo = doslova ‚pravdivé slovo‘, tedy opravdu. Hovorové synonymum je 진짜.","r":["jeong-正"]},{"id":"ko-k3-0234","w":"에어컨","cs":"klimatizace","en":"air conditioner","p":"n","o":"e","ex":"석진 씨, 추워요? 에어컨 끌까요?","exc":"Sokdžine, je ti zima? Mám vypnout klimatizaci? (-ㄹ까요 → mám udělat?)","m":"Zkrácená výpůjčka z anglického air conditioner. Častá spojení: 에어컨을 켜다 (zapnout klimatizaci) a 에어컨을 끄다 (vypnout klimatizaci)."},{"id":"ko-k3-0235","w":"끄다","cs":"vypnout; zhasnout; uhasit","en":"to turn off","p":"v","o":"k","ex":"껐어요. 너무 더우면 말하세요.","exc":"Vypnul jsem ji. Kdyby bylo moc horko, řekni. (-으면 → když, jestli)","m":"Nepravidelné časování ㅡ → 꺼요 (vypnu), minulý čas 껐어요. Používá se pro spotřebiče, světlo (불을 끄다) i oheň. Opak 켜다 (zapnout)."},{"id":"ko-k3-0237","w":"이번","cs":"tentokrát; tento (nadcházející)","en":"this (upcoming) time","p":"o","o":"m","ex":"이번 시험은 어려울 거예요.","exc":"Tahle zkouška bude těžká. (은 → téma; -을 거예요 → bude)","m":"Složené z 이 (tento) + 番 (pořadí, krát, tah). Používá se před podstatnými jmény pro aktuální či nejbližší událost: 이번 주 (tento týden), 이번 시험 (tato zkouška).","r":["beon-番"]}],"gram":{"id":"ko-k3-g11","w":"ㅂ 불규칙","en":"Irregulars: ㅂ","cs":"nepravidelná slovesa a přídavná jména na ㅂ","vy":"U mnoha sloves a přídavných jmen končících na ㅂ (např. 춥다, 어렵다, 덥다, 돕다) se koncové ㅂ mění na 우, jakmile za ním následuje koncovka začínající samohláskou (např. -어요, -(으)면, -(으)ㄹ 거예요). Pouze u sloves 돕다 (pomáhat) a 곱다 (půvabný) se ㅂ před -아/어 mění na 오 (도와요), u ostatních se 우 spojí s -어 do tvaru -워요 (추워요). Před koncovkou začínající souhláskou (např. -고, -는) zůstává ㅂ beze změny.","m":"Ne všechna slova na ㅂ jsou nepravidelná: běžná slovesa jako 입다 (oblékat si), 잡다 (chytit), 씹다 (žvýkat) nebo přídavné jméno 좁다 (úzký) se časují pravidelně (입어요, 좁아요).","s":[["도와요 · 도왔어요 · 도울 거예요","pomáhá · pomáhal · bude pomáhat (돕다)"],["어려워요 · 어려웠어요 · 어려울 거예요","je těžké · bylo těžké · bude těžké (어렵다)"],["추워요 · 추웠어요 · 추울 거예요","je zima · byla zima · bude zima (춥다)"],["돕는 것","pomáhání (před -는 se ㅂ nemění)"],["입어요 (ne 이워요)","oblékám si (입다 si ㅂ zachovává)"],["좁아요","je to úzké (좁다 si ㅂ zachovává)"],["이 문제는 어려워요.","Tenhle úkol je těžký."],["이거 너무 귀여워요.","Tohle je strašně roztomilé."],["서울은 겨울에 정말 추워요.","V Soulu je v zimě opravdu zima."],["TTMIK으로 공부하면, 한국어 공부가 쉬워요.","Když se učíš s Korean 3, studium korejštiny je snadné."],["석진 씨, 추워요? 에어컨 끌까요?","Sokdžine, je ti zima? Mám vypnout klimatizaci?"],["껐어요. 너무 더우면 말하세요.","Vypnul jsem ji. Kdyby ti bylo moc horko, řekni."],["도우면 · 돕고 · 도와서","když pomůžeš · pomoct a · protože pomohl"],["구우면 · 굽고 · 구워서","když upečeš · upéct a · protože upekl"],["어제는 정말 추웠어요.","Včera byla opravdu zima."],["이번 시험은 어려울 거예요.","Tahle zkouška bude těžká."]]}};
Object.assign(MM.mnRoots, {"mun-問":["문","問","ptát se"],"je-題":["제","題","téma, otázka"],"jeong-正":["정","正","správný, rovný"],"beon-番":["번","番","pořadí, krát, tah"]});

